package main

import "fmt"

func getPoint() (int, int) {
	return 42, 100
}

func main() {
	// Zero values
	var i int
	var f float64
	var b bool
	var s string
	fmt.Printf("Zero values: int=%d, float=%f, bool=%t, string=%q\n", i, f, b, s)

	// Multiple assignment
	x, y, z := 10, 20, 30
	fmt.Println("x, y, z:", x, y, z)

	// Swap trick
	x, y = y, x
	fmt.Println("Setelah swap x,y:", x, y)

	// Blank identifier
	_, coordY := getPoint()
	fmt.Println("Hanya y:", coordY)

	_ = z // gunakan z agar tidak error
}
